import java.util.Objects;
class Customer { private final int id; private final String name; private final char gender; Customer(int id,String name,char gender){this.id=id;this.name=name;this.gender=gender;} public int getID(){return id;} public String getName(){return name;} public char getGender(){return gender;} public String toString(){return name+"("+id+")";} }
class Account { private final int id; private final Customer customer; private double balance; Account(int id,Customer customer,double balance){this.id=id;this.customer=customer;this.balance=balance;} Account(int id,Customer customer){this(id,customer,0.0);} public int getID(){return id;} public Customer getCustomer(){return customer;} public double getBalance(){return balance;} public void setBalance(double b){balance=b;} public String getCustomerName(){return customer.getName();} public String toString(){return customer+" balance=$"+String.format("%.2f",balance);} public Account deposit(double amount){if(amount>0)balance+=amount;return this;} public Account withdraw(double amount){if(amount>0&&balance>=amount)balance-=amount;else System.out.println("Amount withdrawn exceeds the current balance!");return this;} }
public class Task09CustomerAccount { public static void main(String[] args){Customer c=new Customer(1,"Yahya",'m');Account a=new Account(100,c,50);System.out.println(a);a.deposit(25).withdraw(10);System.out.println(a);} }
